data class EditorRecoverySession(val client:String,val slot:String,val workspace:String,val namespace:String,val revision:Long,val request:String,val hash:String,val host:String,val count:Int,val revisions:List<EditorRecoveryRevision> = emptyList(),val guard:String?=null){val versions get()=revisions.ifEmpty{listOf(EditorRecoveryRevision(revision,request,hash,host,count))};val removal get()=EditorRecoveryRemoval(client,slot,guard)}
