private fun recoveryRevision(raw:JSONObject):EditorRecoveryRevision {val revision=recoveryUInt(raw,"revision");val request=recoveryString(raw,"request_id");val hash=recoveryString(raw,"snapshot_hash");val host=recoveryString(raw,"host");val count=recoveryUInt(raw,"buffers");check(revision>0&&revision<=4294967295L&&recoveryHex(request,32)&&recoveryHex(hash,64)&&host in listOf("browser","macos","ios","android")&&count<=256){"Malformed private revision metadata."};return EditorRecoveryRevision(revision,request,hash,host,count.toInt())}
