 private suspend fun call(e:Engine,method:String,path:String,body:JSONObject?=null)=transport?.invoke(e,method,path,body) ?: e.request(method,path,body)
 private suspend fun list(w:Workspace,slot:String?=null,after:String?=null):EditorRecoveryCatalogue {val e=w.engine ?: error("Connect before private session recovery.");val runtime=e.sourceWorkspaceID ?: error("Refresh Files before private recovery.");val root=e.sourceRootAddress ?: error("Refresh Files before private recovery.");val raw=call(e,"GET","/api/workspace/recovery"+listOfNotNull(slot?.let{"window_slot=$it"},after?.let{"after=$it"}).let{if(it.isEmpty())"" else "?"+it.joinToString("&")});check(w.engine===e&&e.sourceWorkspaceID==runtime&&e.sourceRootAddress==root){"Private recovery connection changed."};return withContext(Dispatchers.Default){editorRecoveryCatalogue(raw,runtime,root,after)}}
