 suspend fun checkpoint(w:Workspace){val e=w.engine ?: return;val runtime=e.sourceWorkspaceID ?: return;val root=e.sourceRootAddress ?: return;if(writing||busy)return;writing=true
  try{if(bound!==e||this.runtime!=runtime||namespace!=root){bound=e;this.runtime=runtime;namespace=root;client=recoveryToken();revision=0;last=null;pending=null;if(pendingForget?.let{it.runtime!=runtime||it.namespace!=root}==true)pendingForget=null};if(pendingForget!=null)return;val captured=captureEditorRecovery(w).json().toString();if(pending==null&&captured==last)return
