  try{val row=editorRecoverySelectRevision(original,revision);val raw=call(e,"GET","/api/workspace/recovery/${row.client}?revision=${row.revision}&window_slot=${row.slot}");check(raw.get("version")==1&&raw.get("recovery_protocol")==1&&recoveryString(raw,"engine_workspace_id")==runtime&&recoveryString(raw,"client_id")==row.client&&recoveryString(raw,"window_slot")==row.slot&&recoveryString(raw,"workspace_id")==row.workspace&&recoveryString(raw,"namespace")==row.namespace&&recoveryUInt(raw,"revision")==row.revision&&recoveryString(raw,"request_id")==row.request&&recoveryString(raw,"snapshot_hash")==row.hash&&!recoveryBool(raw,"source_effects")&&!recoveryBool(raw,"source_saved")){"Complete private snapshot receipt changed."};val material=recoveryString(raw,"material")
