  }catch(e:CancellationException){throw e}catch(e:Exception){if(id==ticket)notice=e.message.orEmpty()}finally{if(id==ticket)busy=false}
 }

 fun clearReading(){ticket++;busy=false;snapshot=null;readingRevision=null;current={false}}
 suspend fun more(w:Workspace){val original=catalogue ?: return;val cursor=original.next ?: return;if(busy)return;val id=++ticket;busy=true;snapshot=null;readingRevision=null;current={false}
