 suspend fun retryForget(w:Workspace){pendingForget?.let{forget(it.target,w)}}
 suspend fun forget(target:EditorRecoveryRemoval,w:Workspace){if(busy)return;if(writing){notice="Finish the current private checkpoint before removing a session.";return};val e=w.engine ?: return;val runtime=e.sourceWorkspaceID ?: return;val root=e.sourceRootAddress ?: return;val id=++ticket;busy=true;snapshot=null;readingRevision=null;current={false}
  try{val meta=catalogue ?: error("Refresh private sessions before forgetting one.");val guard=target.guard ?: error("This engine did not provide private removal authority.");check(meta.runtime==runtime&&meta.namespace==root){"Private removal connection changed."}
   if(pendingForget==null){check((meta.sessions.map{it.removal}+meta.unreadable.map{it.removal}).contains(target)){"Selected private record changed."};val body=JSONObject().put("version",1).put("workspace",runtime).put("window_slot",target.slot).put("client_id",target.client).put("request_id",recoveryToken()).put("record_guard",guard);pendingForget=PendingForget(body.toString(),target,meta.workspace,root,runtime)}
   val held=pendingForget!!;check(held.target==target&&held.runtime==runtime&&held.namespace==root){"Resolve the original uncertain removal before selecting another session."};val body=JSONObject(held.body);val result=call(e,"POST","/api/workspace/recovery/forget",body)
   check(result.get("version")==1&&result.get("recovery_protocol")==1&&recoveryString(result,"engine_workspace_id")==runtime&&recoveryString(result,"workspace_id")==held.physical&&recoveryString(result,"namespace")==root&&recoveryString(result,"window_slot")==target.slot&&recoveryString(result,"client_id")==target.client&&recoveryString(result,"request_id")==body.getString("request_id")&&recoveryString(result,"guard_hash")==debugHash(guard)&&recoveryBool(result,"forgotten")&&result.get("replayed") is Boolean&&!recoveryBool(result,"source_effects")&&!recoveryBool(result,"source_saved")&&w.engine===e&&e.sourceWorkspaceID==runtime&&e.sourceRootAddress==root&&pendingForget?.body==held.body){"Private removal acknowledgment or connection changed. Exact request retained."}
   pendingForget=null;if(target.client==client){client=recoveryToken();revision=0;pending=null;last=null};catalogue=catalogue?.let{current->current.copy(sessions=current.sessions.filterNot{it.removal==held.target},unreadable=current.unreadable.filterNot{it.removal==held.target})};notice="Original private session forgotten. Current editors and source were retained; replay never removes a replacement."
  }catch(e:CancellationException){throw e}catch(error:Exception){if(id==ticket)notice=error.message.orEmpty()+" Retry the exact original removal or stop retrying and refresh."}finally{if(id==ticket)busy=false}
 }
 val canRestore get()=!busy&&snapshot!=null&&current()
 fun restore(w:Workspace):Boolean{val value=snapshot;if(!canRestore||value==null){notice="Host editor lease changed. Preview again; open drafts were preserved.";return false};return try{restoreEditorRecovery(value,w);snapshot=null;current={false};notice="Recovered draft copies and layout. Existing editors and saved source were retained.";true}catch(e:Exception){notice=e.message.orEmpty();false}}
}
@Composable fun EditorRecoveryView(w:Workspace){val m=w.editorRecovery;val scope=rememberCoroutineScope();var index by remember{mutableIntStateOf(0)};var page by remember{mutableIntStateOf(0)};var selected by remember{mutableStateOf<Map<String,Long>>(emptyMap())};var armed by remember{mutableStateOf<String?>(null)}
 LaunchedEffect(m){if(!m.busy)m.open(w)}
 @Composable fun removal(target:EditorRecoveryRemoval,count:Int?){val confirming=target.guard!=null&&armed==target.guard;TextButton(enabled=!m.busy&&target.guard!=null,onClick={if(!confirming)armed=target.guard else{armed=null;scope.launch{m.forget(target,w)}}}){Text(if(confirming)count?.let{"Confirm forget entire private session ($it retained revisions)"} ?: "Confirm forget unreadable private record" else "Forget private session…")}}
 Column(Modifier.padding(12.dp).widthIn(max=680.dp).heightIn(max=640.dp).verticalScroll(rememberScrollState()),verticalArrangement=Arrangement.spacedBy(8.dp)){
  Text("Editor session recovery");Text(m.notice,fontSize=12.sp);Text("Private checkpoints are draft recovery, not source saves. Recovery adds copies beside current editors. Forget removes the entire selected private session and every retained revision; source and current editors remain unchanged.",fontSize=12.sp)
  TextButton(enabled=!m.busy,onClick={armed=null;scope.launch{m.open(w,m.catalogue?.slot)}}){Text("Refresh sessions")}
  if(m.hasPendingForget){TextButton(enabled=!m.busy,onClick={scope.launch{m.retryForget(w)}}){Text("Retry original private removal")};TextButton(enabled=!m.busy,onClick={m.stopRetryingForget()}){Text("Stop retrying and refresh before another removal")}}
  m.catalogue?.let{catalogue->Row{catalogue.slots.forEach{slot->TextButton(enabled=!m.busy,onClick={armed=null;scope.launch{m.open(w,slot)}}){Text("Window $slot")}}};catalogue.notices.forEach{Text(it,fontSize=12.sp)};catalogue.sessions.forEach{row->key(row.client){val revision=row.versions.firstOrNull{it.revision==selected[row.client]} ?: row.versions.last();Column{Text("Private session ${row.client}",fontSize=12.sp);Row{row.versions.forEach{version->FilterChip(enabled=!m.busy,selected=revision.revision==version.revision,onClick={selected=selected+(row.client to version.revision);m.clearReading();page=0;index=0;armed=null},label={Text("Revision ${version.revision}")})}};TextButton(enabled=!m.busy,onClick={index=0;page=0;scope.launch{m.read(row,w,revision.revision)}}){Text("Read ${revision.host} · ${row.client} · revision ${revision.revision}")};removal(row.removal,row.revisions.size.takeIf{it>0})}}};catalogue.unreadable.forEach{row->key("unreadable-"+row.client){Text("Unreadable private record ${row.client}: ${row.reason}. Contents were not adopted.",fontSize=12.sp);removal(row.removal,null)}};if(catalogue.next!=null){TextButton(enabled=!m.busy,onClick={scope.launch{m.more(w)}}){Text("More private sessions")}}}
  m.snapshot?.let{snapshot->if(snapshot.buffers.isNotEmpty()){val row=snapshot.buffers[index.coerceAtMost(snapshot.buffers.lastIndex)];val scalars=row.text.codePoints().toArray();val count=maxOf(1,(scalars.size+15999)/16000);val shown=page.coerceAtMost(count-1)
   snapshot.buffers.forEachIndexed{i,b->TextButton(onClick={index=i;page=0}){Text(b.address.kind+" · "+b.address.label)}};m.readingRevision?.let{Text("Reading retained revision $it",fontSize=12.sp)};Text(String(scalars,shown*16000,minOf(16000,scalars.size-shown*16000)),fontSize=12.sp);Text("Text page ${shown+1}/$count · "+if(row.address.kind=="generated")"read-only generated text" else "unnamed draft; guarded Save As required",fontSize=12.sp)
   Row{TextButton(enabled=shown>0,onClick={page=shown-1}){Text("Previous text")};TextButton(enabled=shown+1<count,onClick={page=shown+1}){Text("Next text")}};TextButton(enabled=m.canRestore,onClick={m.restore(w)}){Text("Recover complete session as draft copies")}
  }}
 }
}
